    [0, 6, 3,  0, 0, 0,  0, 8, 0],
    [0, 0, 0,  6, 0, 8,  0, 0, 0]
]

# Model definition
model = cp_model.CpModel()

# Create a 9x9 grid of integer variables with domain 1..9
grid = [[model.NewIntVar(1, 9, f'grid_{i}_{j}') for j in range(9)] for i in range(9)]

# Add constraints for the initial values
for i in range(9):
    for j in range(9):
        if input_grid[i][j] != 0:
            model.Add(grid[i][j] == input_grid[i][j])

# Add constraints for rows: all different
for i in range(9):
    model.AddAllDifferent([grid[i][j] for j in range(9)])

# Add constraints for columns: all different
for j in range(9):
    model.AddAllDifferent([grid[i][j] for i in range(9)])

# Add constraints for 3x3 squares: all different
for box_row in range(3):
    for box_col in range(3):
        box_vars = [
            grid[i][j]
            for i in range(box_row * 3, (box_row + 1) * 3)
            for j in range(box_col * 3, (box_col + 1) * 3)
        ]
        model.AddAllDifferent(box_vars)

# Solve the model
solver = cp_model.CpSolver()
status = solver.Solve(model)

if status == cp_model.OPTIMAL or status == cp_model.FEASIBLE:
    solution = {
        'grid': [[solver.Value(grid[i][j]) for j in range(9)] for i in range(9)]
    }
    print(json.dumps(solution, indent=4))
else:
    print("No solution found.")
